package cn.workbench;

import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import static cn.workbench.Records.map;

/** Explicit, revocable department-head delegation and append-only responsibility handover. */
@Service public class OrganizationChanges {
 static final Set<String> PERMISSIONS=Set.of("receive","assign","progress","submit","withdraw","extend","transfer","summarize","comment","upload");
 final Store db;final Records r;final Writes w;final Jsons json;final JdbcTemplate jdbc;
 public OrganizationChanges(Store db,Records r,Writes w,Jsons json,JdbcTemplate jdbc){this.db=db;this.r=r;this.w=w;this.json=json;this.jdbc=jdbc;}
 static Map<String,Object> camel(Map<String,Object> raw){var out=new LinkedHashMap<String,Object>();raw.forEach((k,v)->{StringBuilder key=new StringBuilder();boolean upper=false;for(char c:k.toCharArray()){if(c=='_')upper=true;else {key.append(upper?Character.toUpperCase(c):c);upper=false;}}out.put(key.toString(),v);});return out;}
 List<Map<String,Object>> query(String sql,Object...args){return jdbc.queryForList(sql,args).stream().map(OrganizationChanges::camel).toList();}
 Map<String,Object> delegation(long id,boolean lock){return query("SELECT d.*,u.name AS delegator_name,v.name AS delegate_name FROM scope_delegation d JOIN app_user u ON u.id=d.delegator_id JOIN app_user v ON v.id=d.delegate_user_id WHERE d.id=?"+(lock?" FOR UPDATE":""),id).stream().findFirst().orElseThrow(ApiException::denied);}
 Set<String> permissions(Map<String,Object> d){Object value=json.map("{\"items\":"+d.get("permissionsJson")+"}").get("items");if(!(value instanceof List<?> list))throw ApiException.denied();Set<String> result=new LinkedHashSet<>();for(var item:list){String p=String.valueOf(item);if(!PERMISSIONS.contains(p))throw ApiException.denied();result.add(p);}return Set.copyOf(result);}
 boolean effective(Map<String,Object>d){if(!"ACTIVE".equals(d.get("status"))||Records.instant(d.get("validFrom")).isAfter(Instant.now())||!Records.instant(d.get("validUntil")).isAfter(Instant.now()))return false;var source=db.scope(Jsons.number(d.get("delegatorId")),Jsons.number(d.get("sourceScopeId")));if(source==null||!"DEPT_HEAD".equals(source.get("role"))||!Objects.equals(Jsons.integer(source.get("companyId")),Jsons.integer(d.get("companyId")))||!Objects.equals(Jsons.integer(source.get("deptId")),Jsons.integer(d.get("deptId"))))return false;return member(Jsons.number(d.get("delegateUserId")),Jsons.integer(d.get("companyId")),Jsons.integer(d.get("deptId")));}
 boolean member(long user,int company,int dept){var u=db.user(user);return u!=null&&Boolean.TRUE.equals(u.get("enabled"))&&db.scopes(user).stream().anyMatch(s->Objects.equals(company,s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))&&Objects.equals(dept,s.get("deptId")==null?null:Jsons.integer(s.get("deptId")))&&Set.of("EMPLOYEE","DEPT_HEAD").contains(s.get("role")));}
 Policy.Actor actor(HttpServletRequest request,Policy.Actor ordinary){Object active=request.getSession().getAttribute("delegationId");if(active==null)return ordinary;var d=delegation(Jsons.number(active),false);if(Jsons.number(d.get("delegateUserId"))!=ordinary.uid()||!effective(d)||!Objects.equals(ordinary.company(),Jsons.integer(d.get("companyId")))||!Objects.equals(ordinary.dept(),Jsons.integer(d.get("deptId"))))throw ApiException.denied();var actor=new Policy.Actor(ordinary.uid(),"DEPT_HEAD",Jsons.integer(d.get("companyId")),Jsons.integer(d.get("deptId")),Jsons.number(d.get("sourceScopeId")),Jsons.number(d.get("id")),Jsons.number(d.get("delegatorId")),permissions(d));if(!allowedPath(request,actor))throw ApiException.denied();return actor;}
 boolean allowedPath(HttpServletRequest q,Policy.Actor actor){String path=RolePermissions.path(q),method=q.getMethod();if(path.startsWith("/api/v1/auth/")||path.equals("/api/v1/organization/delegations/leave")||method.equals("GET")&&path.equals("/api/v1/organization/delegations"))return true;if(method.equals("GET"))return path.equals("/api/v1/tasks")||path.matches("/api/v1/tasks/\\d+")||path.equals("/api/v1/sub-tasks/mine")||path.equals("/api/v1/organization/users")||path.equals("/api/v1/organization/departments")||path.matches("/api/v1/attachments/\\d+(/download|/preview|/versions)?");if(method.equals("POST")){if(path.matches("/api/v1/sub-tasks/\\d+/(receive|assign|progress|submit|withdraw|extend|transfer)"))return actor.allows(path.substring(path.lastIndexOf('/')+1));if(path.matches("/api/v1/tasks/\\d+/summarize"))return actor.allows("summarize");if(path.matches("/api/v1/tasks/\\d+/comments"))return actor.allows("comment");return path.equals("/api/v1/attachments")&&actor.allows("upload");}return false;}
 Map<String,Object> snapshot(Long uid,int company,int dept){var user=uid==null?null:db.user(uid);return map("userId",uid,"name",user==null?null:user.get("name"),"companyId",company,"deptId",dept);}
 void initialOwner(Map<String,Object> sub,long owner){if(sub.get("originalOwnerSnapshot")==null)sub.put("originalOwnerSnapshot",snapshot(owner,TaskService.integer(sub,"companyId"),TaskService.integer(sub,"deptId")));}
 void apply(Policy.Actor actor,Map<String,Object> sub,long owner,String reason){int company=TaskService.integer(sub,"companyId"),dept=TaskService.integer(sub,"deptId");if(!member(owner,company,dept))throw TaskService.invalid("New owner must have an active appointment in this department");Long previous=sub.get("ownerId")==null?null:Jsons.number(sub.get("ownerId"));if(Objects.equals(previous,owner))throw TaskService.invalid("New owner must differ from current owner");if(actor.delegationId()!=null&&previous!=null&&!actor.allows("transfer"))throw ApiException.denied();if(previous!=null)initialOwner(sub,previous);else initialOwner(sub,owner);var before=snapshot(previous,company,dept);var after=snapshot(owner,company,dept);jdbc.update("INSERT INTO task_handover(task_id,sub_task_id,company_id,dept_id,previous_owner_id,new_owner_id,actor_id,delegation_id,reason,previous_owner_snapshot,new_owner_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?)",sub.get("taskId"),sub.get("id"),company,dept,previous,owner,actor.uid(),actor.delegationId(),reason,json.write(before),json.write(after));if(!db.assignees(TaskService.number(sub,"id")).contains(owner))db.assign(TaskService.number(sub,"id"),owner);sub.put("ownerId",owner);r.create("TIMELINE",company,dept,TaskService.number(sub,"taskId"),actor.uid(),"RESPONSIBILITY_HANDOVER",map("actorId",actor.uid(),"delegationId",actor.delegationId(),"reason",reason,"previousOwner",before,"newOwner",after));w.audit(actor,"RESPONSIBILITY_HANDOVER",TaskService.number(sub,"id"));}
}
